import os, json, time

ROOT = 'storage/shared/meta/sas'
DASH = f'{ROOT}/dashboard'
PANELS_INDEX = f'{DASH}/panels_index.json'
STATE_PATH = f'{DASH}/dashboard_state.json'

PANELS = {
  "css_comparison": f"{DASH}/css_comparison_logos_v.json",
  "css_recovery":   f"{DASH}/css_recovery_logos_v.json",
  "xl_series":      f"{DASH}/xl_transfer_series_zephyr_v.json",
  "xl_series_ci":   f"{DASH}/xl_transfer_series_ci_zephyr_v.json",
  "surr_gpu":       f"{DASH}/surr_gpu_zephyr_v.json",
  "synthesis":      f"{DASH}/synthesis_overview.json"
}

def _exists(p): return os.path.exists(p)
def _read(p, default=None):
  try:
    with open(p,'r',encoding='utf-8') as f: return json.load(f)
  except Exception: return default
def _write(p, obj):
  os.makedirs(os.path.dirname(p), exist_ok=True)
  with open(p,'w',encoding='utf-8') as f: json.dump(obj, f, indent=2)

# Build panels index (only include existing)
panels_index = _read(PANELS_INDEX, {}) or {}
panels_index['updated_ts'] = time.time()
panels_index.setdefault('xl', {})
for k, path in PANELS.items():
  if _exists(path):
    panels_index['xl' if k.startswith('xl_') else k] = path
_write(PANELS_INDEX, panels_index)

# Assemble dashboard state summary with light embedding + links
state = {
  "updated_ts": time.time(),
  "links": {k: v for k, v in PANELS.items() if _exists(v)},
  "summaries": {}
}
# Fold synthesis overview lightly if present
syn = _read(PANELS["synthesis"])
if isinstance(syn, dict):
  state["summaries"]["synthesis"] = {
    "css": syn.get("css"),
    "xl": syn.get("xl"),
    "surr_gpu": syn.get("surr_gpu"),
    "notes": syn.get("notes")
  }
# Fold CSS comparison if present
css = _read(PANELS["css_comparison"])
if isinstance(css, dict):
  state["summaries"]["css"] = {
    "A_mean_ms": css.get("A_mean_ms"),
    "B_mean_ms": css.get("B_mean_ms"),
    "ratio_B_over_A": css.get("ratio_B_over_A")
  }
# Fold SURR if present
surr = _read(PANELS["surr_gpu"])
if isinstance(surr, dict):
  state["summaries"]["surr_gpu"] = {
    "baseline_ms": surr.get("baseline", {}).get("mean_ms"),
    "offsets": surr.get("offsets")
  }
# Fold XL series CI if present (link only)
if _exists(PANELS["xl_series_ci"]):
  state.setdefault("notes", []).append("XL series CI available.")

_write(STATE_PATH, state)
print(json.dumps({"panels_index": PANELS_INDEX, "dashboard_state": STATE_PATH, "links": state["links"]}, indent=2))
